async function* listAll(client, params = {}) {
  let pageToken;                       // opaque continuation token
  do {
    const page = await client.list({ limit: 100, pageToken, ...params });
    yield* page.data;
    pageToken = page.next_page_token;  // absent at the end
  } while (pageToken);
}
for await (const item of listAll(client)) consume(item);
